if doc.is_new() and kra_setup.status != "Approved":
    frappe.throw("KRA and Goal Setup " + doc.kra_and_goal_setup + " is not approved yet (status: " + str(kra_setup.status) + "). Ask your Line Manager to approve it first.")

settings = None
yn = 1
settings_name = frappe.db.get_value("Performance Settings",
    {"company": doc.company, "cycle_year": doc.cycle_year}, "name")
if settings_name:
    settings = frappe.get_doc("Performance Settings", settings_name)
    yn = doc.cycle_year - (settings.base_year or doc.cycle_year) + 1

if not doc.goal_progression:
    for row in kra_setup.kra_and_goal_detail:
        doc.append("goal_progression", {
            "kra_name": row.kra_name,
            "goal_name": row.kra_name + " Y" + str(yn),
            "goal_description": row.goal_description,
            "weightage_": row.get("weightage_")
        })

if not doc.self_review and settings:
    for criteria in settings.rating_criteria:
        doc.append("self_review", {
            "criteria_name": criteria.criteria_name,
            "weightage_": criteria.get("weightage_")
        })

if not doc.manager_review and settings:
    for criteria in settings.rating_criteria:
        doc.append("manager_review", {
            "criteria_name": criteria.criteria_name,
            "weightage_": criteria.get("weightage_")
        })

# back-fill the user/manager fields the notifications and permission
# queries depend on
if doc.employee:
    emp = frappe.get_doc("Employee", doc.employee)
    doc.employee_name = doc.employee_name or emp.employee_name
    doc.employee_user = doc.employee_user or emp.get("user_id")
    doc.company = doc.company or emp.company
    doc.department = doc.department or emp.department
    doc.designation = doc.designation or emp.designation
    if emp.reports_to:
        doc.reports_to = doc.reports_to or emp.reports_to
        doc.line_manager_user = doc.line_manager_user or frappe.db.get_value(
            "Employee", emp.reports_to, "user_id")
        doc.line_manager_name = doc.line_manager_name or frappe.db.get_value(
            "Employee", emp.reports_to, "employee_name")

# --- authoritative scoring (MP-Q4/Q5/Q6, 2026-09-17). Same formula as the client script, but the
# server value wins; the browser only previews. Scale: every table is 0-5, final = mean of the three.
goal_total = 0.0
for row in doc.goal_progression:
    p_man = frappe.utils.flt(row.manager_adjusted_progression_)
    p_emp = frappe.utils.flt(row.employee_progression_)
    prog = p_man if p_man > 0 else p_emp
    goal_total = goal_total + (prog / 100.0) * (frappe.utils.flt(row.weightage_) / 100.0) * 5.0
self_total = 0.0
for row in doc.self_review:
    self_total = self_total + frappe.utils.flt(row.self_rating) * 5.0 * frappe.utils.flt(row.weightage_) / 100.0
mgr_total = 0.0
for row in doc.manager_review:
    mgr_total = mgr_total + frappe.utils.flt(row.manager_rating) * 5.0 * frappe.utils.flt(row.weightage_) / 100.0
doc.total_goal_score = frappe.utils.flt(goal_total, 2)
doc.total_self_score = frappe.utils.flt(self_total, 2)
doc.total_manager_score = frappe.utils.flt(mgr_total, 2)
doc.final_score = frappe.utils.flt((doc.total_goal_score + doc.total_self_score + doc.total_manager_score) / 3.0, 2)
if doc.final_score >= 4.75:
    doc.performance_band = "Outstanding"
elif doc.final_score >= 4.0:
    doc.performance_band = "Exceeds Expectations"
elif doc.final_score >= 3.0:
    doc.performance_band = "Meets Expectations"
elif doc.final_score >= 2.0:
    doc.performance_band = "Fair"
else:
    doc.performance_band = "Needs Improvement"

